--- a/runtime/scheduler/launch_throttler.cc
+++ b/runtime/scheduler/launch_throttler.cc
@@ -12,6 +12,34 @@
+// simple EWMA per-peer latency estimator used to compute safe concurrency
+double PeerEstimator::update(int peer_id, double last_latency_ms) {
+  auto &s = peers_[peer_id];
+  s.ewma = s.ewma == 0 ? last_latency_ms : s.alpha * last_latency_ms + (1 - s.alpha) * s.ewma;
+  // budget inversely proportional to observed latency, clamped [1, max_budget]
+  return std::max(1, (int)std::min((double)max_budget_, std::round(max_budget_ * (baseline_ms_ / (s.ewma + 1e-6)))));
+}
+
+void LaunchThrottler::maybe_schedule(Function&& f) {
+  int budget = peer_estimator_.budget_for(peer_id_);
+  if (inflight_for_peer_[peer_id_] >= budget) {
+    // requeue non-critical tasks to batch later
+    pending_queue_.push_back(std::move(f));
+    metrics_.inc("throttled_kernel_count");
+    return;
+  }
+  inflight_for_peer_[peer_id_]++;
+  executor_.post([this, f = std::move(f), peer = peer_id_](){ f(); inflight_complete(peer); });
+}
